const now=new Date().toISOString();
return [{json:{
  generated_at:now,
  campaign_id:'daily-content-acquisition-2026',
  prompt:'Create two original Filtra.AI acquisition drafts for today. Return ONLY valid JSON with keys devto_title, devto_body, buffer_post. The DEV.to draft should be a useful technical/business article about online reputation management, customer reviews, AI-assisted reputation workflows, or a closely related SaaS problem; 700-1100 words, practical, non-spammy, with a soft mention of Filtra.AI at the end. The Buffer draft should be a concise social post under 700 characters, useful and human, with no mass-outreach language. Do not invent customer results, prices, partnerships, or statistics. Write in English unless the topic naturally benefits from another language.'
}}];

const source=$json||{};
let parsed=null;
try {
  const raw=source.choices?.[0]?.message?.content;
  if(raw) {
    const cleaned=String(raw).replace(/^\s*\`\`\`json\s*/i,'').replace(/\s*\`\`\`\s*$/,'').trim();
    parsed=JSON.parse(cleaned);
  }
} catch {}
if(!parsed || !parsed.devto_title || !parsed.devto_body || !parsed.buffer_post) {
  parsed={
    devto_title:'How AI Can Turn Customer Reviews Into a Reputation Workflow',
    devto_body:'Customer reviews are more than a score on a directory. They are a stream of operational feedback about expectations, service quality, communication and trust. A practical reputation workflow starts by collecting reviews, identifying recurring themes, prioritizing the issues that matter most, and making the response process consistent.\n\nAI can help summarize large volumes of feedback, group similar complaints, surface urgent patterns and prepare response drafts. The important part is keeping a human review step where accuracy, tone and context matter. Automation should reduce repetitive work, not manufacture feedback or send generic replies.\n\nFor SaaS teams, the same workflow can connect review monitoring with internal tasks: detect a recurring complaint, classify it, create a follow-up, and measure whether the issue keeps appearing. This makes reputation management an operational loop rather than a once-a-month report.\n\nFiltra.AI is designed around this kind of workflow: turning reputation signals into structured actions so teams can spend less time watching dashboards and more time improving the customer experience.',
    buffer_post:'Customer reviews can be an operating signal, not just a score. AI can group recurring complaints, surface patterns and prepare response drafts while keeping humans in control. The goal is less dashboard watching and more time fixing the customer experience. #SaaS #CustomerExperience #ReputationManagement'
  };
}
return [{json:{campaign_id:'daily-content-acquisition-2026',generated_at:new Date().toISOString(),...parsed}}];
